module clkgenerator #(
    parameter PERIOD = 10
) (
    output reg clk
);


reg clk_reg = 0;
integer counter = 0;

assign clk = clk_reg;

always @(posedge clk) begin

    counter <= counter + 1;

    if(counter >= (PERIOD/2)) begin

        clk_reg <= ~clk_reg;

        counter <= 0;
    end

end
endmodule
